import re


_VERSION_RE = re.compile(r"\A(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\Z")
_HEADER_RE = re.compile(
    r"\A(?P<type>[a-z]+)(?:\((?P<scope>[^()]+)\))?(?P<breaking>!)?: (?P<text>.*)\Z"
)


def next_version(current, commits):
    """The version after `current`, decided by the commit messages. See TASK.md."""
    if not isinstance(current, str) or _VERSION_RE.fullmatch(current) is None:
        raise ValueError("current must be MAJOR.MINOR.PATCH without leading zeros")

    major, minor, patch = (int(part) for part in current.split("."))
    strongest = 0  # 0: none, 1: fix, 2: feature, 3: breaking

    for message in commits:
        if not isinstance(message, str):
            continue
        lines = message.splitlines()
        if not lines:
            continue
        header = _HEADER_RE.fullmatch(lines[0])
        if header is None:
            continue

        commit_type = header.group("type")
        if header.group("breaking") or any(
            line.startswith(("BREAKING CHANGE: ", "BREAKING-CHANGE: "))
            for line in lines[1:]
        ):
            change = 3
        elif commit_type == "feat":
            change = 2
        elif commit_type == "fix":
            change = 1
        else:
            change = 0
        strongest = max(strongest, change)

    if strongest == 3:
        if major == 0:
            return f"0.{minor + 1}.0"
        return f"{major + 1}.0.0"
    if strongest == 2:
        if major == 0:
            return f"0.{minor}.{patch + 1}"
        return f"{major}.{minor + 1}.0"
    if strongest == 1:
        return f"{major}.{minor}.{patch + 1}"
    return current
